\deleted{\unsure{aussi|ainsi}} change \deleted{par} $\{\unsure{x|f},\unsure{y|g}\}$ en $\{\xi^2\unsure{x|f},\xi^{\unsure{3|2}}\unsure{y|g}\}$,
\figure{\begin{tikzpicture}[x=.007cm,y=-.007cm,line cap=round]
